  token: NewApiToken,
  limit: number,
  now: IsoTimestamp,
): Promise<ApiToken | null> {
  const db = getDb();
  const usable = db
    .select({ id: apiTokens.id })
    .from(apiTokens)
    .where(
      and(
        orgPredicate(apiTokens.orgId, token.orgId),
        eq(apiTokens.userId, token.userId),
        isNull(apiTokens.revokedAt),
        gt(apiTokens.expiresAt, now),
