/**
 * Personal API tokens: issue, list, revoke and authenticate.
 *
 * Must call (do not reimplement): assertCan, assertOrgScope, emit, subscribe, hashToken, randomToken
 */
import { emit, subscribe } from "@/lib/event-bus";
import { hashToken, randomToken } from "@/lib/hash";
import { assertCan } from "@/lib/permissions";
import { assertOrgScope } from "@/lib/tenant";
import { createApiTokenSchema } from "@/schemas/api-token";
import * as apiTokenRepo from "@/server/repositories/api-token-repository";
import * as memberRepo from "@/server/repositories/member-repository";
import * as orgRepo from "@/server/repositories/organization-repository";
import { toIsoTimestamp } from "@/types/common";
import { envelope, orgResource, requireFound } from "./_support";
import type { CreateApiTokenInput } from "@/schemas/api-token";
import type { ApiToken } from "@/types/api-token";
import type { OrgId, UserId } from "@/types/common";
import type { Unsubscribe } from "@/types/event";
import type { Actor } from "@/types/member";

const MAX_USABLE_TOKENS = 5;
const SECRET_PREFIX = "tfk_";
const PREFIX_LENGTH = 12;
const DAY_MS = 24 * 60 * 60 * 1000;

export async function createApiToken(
  actor: Actor,
  input: CreateApiTokenInput,
): Promise<{ token: string; apiToken: ApiToken }> {
  const parsed = createApiTokenSchema.parse(input);
  assertOrgScope(actor, parsed.orgId);
  if (parsed.scope === "write") {
    assertCan(actor, "api_token:create_write", orgResource(parsed.orgId));
  }

  const token = `${SECRET_PREFIX}${randomToken()}`;
  const now = new Date();
  const created = await apiTokenRepo.insertApiTokenWithinLimit(
    {
      orgId: parsed.orgId,
      userId: actor.userId,
      name: parsed.name,
      scope: parsed.scope,
      prefix: token.slice(0, PREFIX_LENGTH),
      tokenHash: hashToken(token),
      expiresAt: toIsoTimestamp(
        new Date(now.getTime() + parsed.expiresInDays * DAY_MS),
      ),
      createdAt: toIsoTimestamp(now),
    },
    MAX_USABLE_TOKENS,
    toIsoTimestamp(now),
  );
  if (created === null) {
    throw new Error(
      `At most ${MAX_USABLE_TOKENS} usable API tokens are allowed per organization`,
    );
  }

  await emit("api_token.created", {
    ...envelope(created.orgId, actor.userId),
    tokenId: created.id,
    userId: created.userId,
    name: created.name,
    scope: created.scope,
  });

  return { token, apiToken: created };
}

export async function listApiTokens(
  actor: Actor,
  orgId: OrgId,
  userId: UserId = actor.userId,
): Promise<readonly ApiToken[]> {
  assertOrgScope(actor, orgId);
  if (userId !== actor.userId) {
    assertCan(actor, "api_token:manage_any", orgResource(orgId));
  }
  return apiTokenRepo.listApiTokens(orgId, userId);
}

export async function revokeApiToken(
  actor: Actor,
  orgId: OrgId,
  tokenId: string,
): Promise<ApiToken> {
  assertOrgScope(actor, orgId);
  const existing = requireFound(
    await apiTokenRepo.findApiTokenById(orgId, tokenId),
    "ApiToken",
    tokenId,
  );
  if (existing.userId !== actor.userId) {
    assertCan(actor, "api_token:manage_any", orgResource(orgId));
  }
  if (existing.revokedAt !== null) return existing;

  return revokeAndAudit(existing, actor.userId);
}

/** Resolves the acting principal for a secret, or `null` if it is unusable. */
export async function authenticateApiToken(
  token: string,
): Promise<Actor | null> {
  const found = await apiTokenRepo.findApiTokenByHash(hashToken(token));
  if (found === null || found.revokedAt !== null) return null;

  const now = toIsoTimestamp(new Date());
  if (found.expiresAt <= now) return null;

  const org = await orgRepo.findOrgById(found.orgId);
  if (org === null || org.archivedAt !== null) return null;

  const member = await memberRepo.findMember(found.orgId, found.userId);
  if (member === null || member.status !== "active") return null;

  await apiTokenRepo.touchLastUsed(found.id, now);

  return {
    userId: found.userId,
    orgId: found.orgId,
    role: found.scope === "read" ? "viewer" : member.role,
  };
}

async function revokeAndAudit(
  token: ApiToken,
  actorId: UserId,
): Promise<ApiToken> {
  const revoked = await apiTokenRepo.markRevoked(
    token.orgId,
    token.id,
    toIsoTimestamp(new Date()),
  );
  // Lost a race with another revoker: they audited it.
  if (revoked === null) {
    return requireFound(
      await apiTokenRepo.findApiTokenById(token.orgId, token.id),
      "ApiToken",
      token.id,
    );
  }

  await emit("api_token.revoked", {
    ...envelope(revoked.orgId, actorId),
    tokenId: revoked.id,
    userId: revoked.userId,
  });
  return revoked;
}

/** Revokes a removed member's tokens; the remover is the audited actor. */
export function registerApiTokenListeners(): Unsubscribe {
  return subscribe("member.removed", async (payload) => {
    const tokens = await apiTokenRepo.listUnrevokedForUser(
      payload.orgId,
      payload.userId,
    );
    for (const token of tokens) {
      await revokeAndAudit(token, payload.actorId as UserId);
    }
  });
}
